import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = read();
            }
            return res;
        }

        public char nextChar() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return 0;
                c = read();
            }
            return (char) c;
        }
    }

    static class FastOutput {
        private final OutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;

        public FastOutput(OutputStream out) {
            this.out = out;
        }

        public void write(byte b) throws IOException {
            if (head >= buffer.length) {
                flush();
            }
            buffer[head++] = b;
        }

        public void writeInt(long v) throws IOException {
            if (v == 0) {
                write((byte) '0');
                return;
            }
            if (v < 0) {
                write((byte) '-');
                v = -v;
            }
            int d = 0;
            byte[] digits = new byte[20];
            while (v > 0) {
                digits[d++] = (byte) ('0' + (v % 10));
                v /= 10;
            }
            while (d > 0) {
                write(digits[--d]);
            }
        }

        public void flush() throws IOException {
            if (head > 0) {
                out.write(buffer, 0, head);
                head = 0;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);

        int N = in.nextInt();
        int M = in.nextInt();
        int P = in.nextInt();

        int[] R = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            R[i] = i;
        }

        int[] C = new int[M + 1];
        for (int j = 1; j <= M; j++) {
            C[j] = j;
        }

        for (int p = 0; p < P; p++) {
            char op = in.nextChar();
            int a = in.nextInt();
            int b = in.nextInt();
            if (op == 'L') {
                int temp = R[a];
                R[a] = R[b];
                R[b] = temp;
            } else if (op == 'C') {
                int temp = C[a];
                C[a] = C[b];
                C[b] = temp;
            }
        }

        for (int i = 1; i <= N; i++) {
            long base = (long) (R[i] - 1) * M;
            for (int j = 1; j <= M; j++) {
                out.writeInt(base + C[j]);
                if (j < M) {
                    out.write((byte) ' ');
                }
            }
            out.write((byte) '\n');
        }

        out.flush();
    }
}
