const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextToken() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        const start = offset;
        while (offset < buffer.length && buffer[offset] > 32) {
            offset++;
        }
        return buffer.toString('ascii', start, offset);
    }

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return 0;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const tokenN = nextToken();
    if (!tokenN) return;
    const N = parseInt(tokenN, 10);
    const M = nextInt();
    const P = nextInt();

    const row = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) {
        row[i] = i;
    }

    const col = new Int32Array(M + 1);
    for (let j = 1; j <= M; j++) {
        col[j] = j;
    }

    for (let k = 0; k < P; k++) {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        const op = buffer[offset++];
        const a = nextInt();
        const b = nextInt();

        if (op === 76) { // 'L'
            const tmp = row[a];
            row[a] = row[b];
            row[b] = tmp;
        } else if (op === 67) { // 'C'
            const tmp = col[a];
            col[a] = col[b];
            col[b] = tmp;
        }
    }

    const outBufSize = 65536;
    const outBuf = Buffer.allocUnsafe(outBufSize);
    let outOffset = 0;

    function flush() {
        if (outOffset > 0) {
            process.stdout.write(outBuf.subarray(0, outOffset));
            outOffset = 0;
        }
    }

    for (let i = 1; i <= N; i++) {
        const rVal = (row[i] - 1) * M;
        for (let j = 1; j <= M; j++) {
            let val = rVal + col[j];

            let len = 0;
            let temp = val;
            while (temp > 0) {
                len++;
                temp = (temp / 10) | 0;
            }

            if (outOffset + len + 1 > outBufSize) {
                flush();
            }

            let endPos = outOffset + len;
            temp = val;
            while (temp > 0) {
                endPos--;
                outBuf[endPos] = 48 + (temp % 10);
                temp = (temp / 10) | 0;
            }
            outOffset += len;

            if (j === M) {
                outBuf[outOffset++] = 10; // '\n'
            } else {
                outBuf[outOffset++] = 32; // ' '
            }
        }
    }

    flush();
}

